<template><article class="card tip-card"><div class="tip-top"><span class="tag">{{pick.league||'Football'}}</span><span class="confidence" v-if="pick.confidence">{{pick.confidence}}% confidence</span></div><div v-if="pick.matchId?.homeTeamId || pick.matchId?.awayTeamId" class="fixture-teams"><TeamLogo :src="pick.matchId?.homeTeamId?.logo" :name="pick.matchId?.homeTeamId?.name" size="sm"/><b>{{pick.matchId?.homeTeamId?.shortName||pick.matchId?.homeTeamId?.name||fixture}}</b><span>vs</span><b>{{pick.matchId?.awayTeamId?.shortName||pick.matchId?.awayTeamId?.name||'Away'}}</b><TeamLogo :src="pick.matchId?.awayTeamId?.logo" :name="pick.matchId?.awayTeamId?.name" size="sm"/></div><div v-else class="fixture">{{fixture}}</div><div class="prediction">{{pick.prediction}}</div><div class="meta">{{formatDate(pick.createdAt||pick.publishedAt)}} · @{{pick.tipsterId?.name||'tipster'}}</div><div class="tip-bottom"><span class="odds">Odds {{Number(pick.odds||0).toFixed(2)}}</span><button class="btn" @click="handlePlay">{{auth.isLoggedIn?'Play pick':'Sign up to play'}}</button></div><div v-if="show" class="play-box"><b>Add to My Picks</b><p class="muted small">Choose a virtual stake to track your potential return. No payment is taken here.</p><input v-model.number="stake" type="number" min="1" step="1" placeholder="Stake (GHS)"/><div class="small" style="margin:8px 0">Potential return: <b>GHS {{(stake*Number(pick.odds||1)).toFixed(2)}}</b></div><div style="display:flex;gap:8px"><button class="btn" @click="save">{{busy?'Saving…':'Add pick'}}</button><button class="ghost" @click="show=false">Cancel</button></div><div v-if="error" class="error" style="margin-top:8px">{{error}}</div></div></article></template>
<script setup lang="ts">import {computed,ref} from 'vue';import {useAuth} from '../stores/auth';import {api} from '../services/api';import {useRouter} from 'vue-router';import TeamLogo from './TeamLogo.vue';const props=defineProps<{pick:any}>();const auth=useAuth(),router=useRouter(),show=ref(false),stake=ref(10),busy=ref(false),error=ref('');const fixture=computed(()=>props.pick.fixture||'Upcoming fixture');function formatDate(v:any){return v?new Date(v).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'Published pick'}function handlePlay(){if(!auth.isLoggedIn){router.push({path:'/login',query:{redirect:'/picks'}});return}show.value=true}async function save(){busy.value=true;error.value='';try{await api.post('/me/picks',{predictionId:props.pick._id,stake:stake.value});show.value=false;alert('Pick added to My Picks')}catch(e:any){error.value=e.message}finally{busy.value=false}}</script>
<style scoped>.fixture-teams{display:flex;align-items:center;justify-content:center;gap:8px;margin:15px 0;font-size:13px}.fixture-teams span{color:var(--muted);font-size:11px} .play-box{margin-top:15px;padding-top:15px;border-top:1px solid var(--line)}.play-box input{width:100%;padding:10px;border:1px solid var(--line);border-radius:9px;margin:8px 0}</style>
